CREATE TABLE IF NOT EXISTS restaurant_state (id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 1,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS restaurant_images (id TEXT PRIMARY KEY,mime TEXT NOT NULL,bytes BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS restaurant_sessions (token TEXT PRIMARY KEY,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS restaurant_attempts (id TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS restaurant_events (id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 1,payload TEXT NOT NULL);
INSERT OR IGNORE INTO restaurant_events(id,revision,payload) VALUES(1,1,'[{"id":"demo-conciertos","title":"Conciertos · Música en directo","description":"Una cena con ritmo propio. Disfruta de nuestra cocina mientras la música en directo pone la banda sonora a una velada para compartir.\n\nConsulta la próxima actuación y reserva tu mesa.\n\nEjemplo de demostración: antes de mostrarlo, añade artista, fecha, horario, condiciones de acceso y contacto para reservas.","date":"","expiresOn":"","imageSrc":"","buttonLabel":"","buttonUrl":"","active":false,"translations":{"en":{"title":"Concerts · Live music","description":"Dinner with a rhythm of its own. Enjoy our food while live music sets the mood for an evening together.\n\nAsk about the next performance and book your table.\n\nDemo example: before showing this event, add the artist, date, time, admission conditions and booking contact."},"de":{"title":"Konzerte · Livemusik","description":"Ein Abendessen mit eigenem Rhythmus. Genießen Sie unsere Küche, während Livemusik für die passende Atmosphäre sorgt.\n\nErkundigen Sie sich nach dem nächsten Auftritt und reservieren Sie Ihren Tisch.\n\nDemobeispiel: Ergänzen Sie vor der Veröffentlichung Künstler, Datum, Uhrzeit, Einlassbedingungen und Kontakt für Reservierungen."}}},{"id":"demo-cumpleanos","title":"Cumpleaños · Celebra tu día con nosotros","description":"Reúne a tus personas favoritas y celebra un cumpleaños alrededor de una buena mesa. Cuéntanos cuántos seréis y cómo te gustaría celebrarlo para consultar las opciones del restaurante.\n\nPregunta por disponibilidad, propuestas para grupos y necesidades alimentarias.\n\nEjemplo de demostración: antes de mostrarlo, confirma capacidad, menús, precios, condiciones para la tarta y contacto para reservas.","date":"","expiresOn":"","imageSrc":"","buttonLabel":"","buttonUrl":"","active":false,"translations":{"en":{"title":"Birthdays · Celebrate your day with us","description":"Bring your favourite people together and celebrate a birthday over a good meal. Tell us how many guests you expect and how you would like to celebrate so we can discuss the restaurant’s options.\n\nAsk about availability, group dining and dietary requirements.\n\nDemo example: before showing this event, confirm capacity, menus, prices, cake arrangements and booking contact."},"de":{"title":"Geburtstage · Feiern Sie Ihren Tag mit uns","description":"Versammeln Sie Ihre Lieblingsmenschen und feiern Sie einen Geburtstag bei einem guten Essen. Teilen Sie uns mit, wie viele Gäste kommen und wie Sie feiern möchten, damit wir die Möglichkeiten des Restaurants besprechen können.\n\nFragen Sie nach Verfügbarkeit, Angeboten für Gruppen und besonderen Ernährungsbedürfnissen.\n\nDemobeispiel: Bestätigen Sie vor der Veröffentlichung Kapazität, Menüs, Preise, Regelungen für die Geburtstagstorte und Kontakt für Reservierungen."}}}]');
CREATE TABLE IF NOT EXISTS restaurant_socials (id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 1,payload TEXT NOT NULL);
INSERT OR IGNORE INTO restaurant_socials(id,revision,payload) VALUES(1,1,'{"instagram":"","facebook":""}');
